const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ===== hero canvas: original animated plant silhouette scene =====
   Drawn programmatically — towers, tanks, flare, stacks — with slow
   light drift and rising flue wisps. 100% original artwork. */
(function(){
  const c=document.getElementById('heroCanvas'),x=c.getContext('2d');
  let W,H,t=0;
  function size(){W=c.width=c.offsetWidth;H=c.height=c.offsetHeight}
  size();addEventListener('resize',size);
  // wisps rising from stacks
  const wisps=[];for(let i=0;i<26;i++)wisps.push({sx:0,y:Math.random(),r:6+Math.random()*14,o:.04+Math.random()*.07,v:.0008+Math.random()*.0014,drift:Math.random()*40-20,stack:Math.floor(Math.random()*3)});
  function plant(bx,by,s,col){
    x.fillStyle=col;
    // columns
    x.fillRect(bx,by-150*s,16*s,150*s);
    x.fillRect(bx+30*s,by-210*s,20*s,210*s);
    x.fillRect(bx+70*s,by-120*s,14*s,120*s);
    // sphere tank
    x.beginPath();x.arc(bx+130*s,by-26*s,26*s,0,7);x.fill();
    // boxes
    x.fillRect(bx+170*s,by-60*s,70*s,60*s);
    x.fillRect(bx+250*s,by-95*s,26*s,95*s);
    // pipe rack
    x.fillRect(bx,by-8*s,290*s,4*s);
    // stacks
    x.fillRect(bx+300*s,by-180*s,10*s,180*s);
    x.fillRect(bx+322*s,by-150*s,10*s,150*s);
  }
  function tick(){
    t+=.004;
    // sky gradient with slow hue drift
    const g=x.createLinearGradient(0,0,W,H);
    const k=(Math.sin(t)+1)/2;
    g.addColorStop(0,'#051C32');
    g.addColorStop(.55,'rgb('+(10+k*6)+','+(46+k*10)+','+(77+k*14)+')');
    g.addColorStop(1,'#0E436B');
    x.fillStyle=g;x.fillRect(0,0,W,H);
    // subtle horizon glow
    const hg=x.createRadialGradient(W*.78,H*.78,0,W*.78,H*.78,W*.5);
    hg.addColorStop(0,'rgba(224,122,31,.16)');hg.addColorStop(1,'rgba(224,122,31,0)');
    x.fillStyle=hg;x.fillRect(0,0,W,H);
    const base=H*.97;
    // far silhouette
    plant(W*.50,base,1.05,'rgba(8,32,54,.9)');
    // near silhouette
    plant(W*.70,base,1.5,'rgba(4,18,32,.95)');
    // flare flame on far stack
    const fx=W*.50+305,fy=base-190;
    const fl=4+Math.sin(t*40)*1.6;
    const fg=x.createRadialGradient(fx,fy,0,fx,fy,26);
    fg.addColorStop(0,'rgba(255,176,102,.9)');fg.addColorStop(.5,'rgba(224,122,31,.45)');fg.addColorStop(1,'rgba(224,122,31,0)');
    x.fillStyle=fg;x.beginPath();x.arc(fx,fy,18+fl,0,7);x.fill();
    // blinking beacon lights
    const blink=(Math.sin(t*30)+1)/2;
    x.fillStyle='rgba(255,90,90,'+(.4+.6*blink)+')';
    x.beginPath();x.arc(W*.50+40,base-212,3,0,7);x.fill();
    x.beginPath();x.arc(W*.70+45,base-318,3.4,0,7);x.fill();
    // rising wisps
    for(const w of wisps){
      w.y-=w.v; if(w.y<0){w.y=1;}
      const sxs=[W*.50+305,W*.50+327,W*.70+465];
      const wx=sxs[w.stack]+Math.sin(w.y*9+t*8)*w.drift;
      const wy=(base-185)*(w.stack<2?1:1)- (1-w.y)*H*.5;
      x.fillStyle='rgba(180,205,225,'+(w.o*w.y)+')';
      x.beginPath();x.arc(wx,wy,w.r*(1.6-w.y*.6),0,7);x.fill();
    }
    if(!reduced)requestAnimationFrame(tick);
  }
  tick();
})();

/* header solid on scroll */
const hdr=document.getElementById('hdr'),bar=document.getElementById('progress');
addEventListener('scroll',()=>{
  const solid=scrollY>60;
  hdr.classList.toggle('solid',solid);
  const h=document.documentElement;
  bar.style.width=(scrollY/(h.scrollHeight-h.clientHeight)*100)+'%';
},{passive:true});

/* reveals */
/* threshold must stay at 0 with a bottom rootMargin: a percentage threshold can
   never be met by blocks taller than the viewport (e.g. the project register on
   a phone), which left them stuck at opacity:0 forever. */
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:0,rootMargin:'0px 0px -8% 0px'});
document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
/* safety net: anything still hidden after load gets revealed */
addEventListener('load',()=>setTimeout(()=>{
  document.querySelectorAll('.reveal:not(.in)').forEach(el=>{
    const r=el.getBoundingClientRect();
    if(r.top<innerHeight&&r.bottom>0)el.classList.add('in');
  });
},600));

/* counters */
const cio=new IntersectionObserver(es=>es.forEach(e=>{
  if(!e.isIntersecting)return;cio.unobserve(e.target);
  const el=e.target,end=+el.dataset.count,t0=performance.now();
  (function step(t){const k=Math.min(1,(t-t0)/1200);
    el.textContent=Math.round(end*(1-Math.pow(1-k,3))).toLocaleString();
    if(k<1)requestAnimationFrame(step)})(t0);
}),{threshold:.6});
document.querySelectorAll('[data-count]').forEach(el=>cio.observe(el));

/* ============================================================
   RWMSD anchored popover (Digital Twin step 02)
   ============================================================ */
(function(){
  const btn=document.getElementById('rwmsdBtn'), pop=document.getElementById('rwmsdPop');
  if(!btn||!pop)return;
  const M=16, BASE=0;
  const col=btn.closest("ul.steps")||btn.parentElement;
  const reduced=()=>!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches);
  const isOpen=()=>btn.getAttribute('aria-expanded')==='true';

  function place(){
    pop.classList.remove('above');
    pop.style.left=BASE+'px';
    let r=pop.getBoundingClientRect();
    const c=col.getBoundingClientRect();
    const minL=Math.max(M,c.left), maxR=Math.min(window.innerWidth-M,Math.max(c.right,c.left+r.width));
    let shift=0;
    if(r.right>maxR)shift=maxR-r.right;
    if(r.left+shift<minL)shift=minL-r.left;
    if(shift)pop.style.left=(BASE+shift)+'px';
    r=pop.getBoundingClientRect();
    if(r.bottom>window.innerHeight-M && r.top-r.height-24>M)pop.classList.add('above');
    const b=btn.getBoundingClientRect();
    r=pop.getBoundingClientRect();
    let ax=b.left+Math.min(b.width/2,42)-r.left-6;
    ax=Math.max(14,Math.min(r.width-26,ax));
    pop.style.setProperty('--rw-ax',ax+'px');
  }

  function open(){
    pop.hidden=false;
    btn.setAttribute('aria-expanded','true');
    place();
    if(reduced())pop.classList.add('open');
    else requestAnimationFrame(()=>pop.classList.add('open'));
    window.addEventListener('resize',place);
    window.addEventListener('scroll',place,{passive:true});
  }
  function close(){
    if(!isOpen())return;
    btn.setAttribute('aria-expanded','false');
    pop.classList.remove('open');
    window.removeEventListener('resize',place);
    window.removeEventListener('scroll',place);
    const done=()=>{if(!isOpen())pop.hidden=true;};
    if(reduced())done();else setTimeout(done,180);
  }

  btn.addEventListener('click',e=>{e.preventDefault();isOpen()?close():open();});
  document.addEventListener('pointerdown',e=>{
    if(!isOpen())return;
    if(!pop.contains(e.target)&&!btn.contains(e.target))close();
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'&&isOpen()){e.preventDefault();close();btn.focus();}
  });
})();

